// Input validation layer
const input = $input.first().json.body || {};

// Validation rules
const required = ['name', 'action'];
const missing = required.filter(field => !input[field]);

if (missing.length > 0) {
  return {
    json: {
      valid: false,
      error: `Missing required fields: ${missing.join(', ')}`,
      input: input
    }
  };
}

// Sanitize and structure
const sanitized = {
  name: String(input.name).trim().substring(0, 100),
  action: ['create', 'update', 'delete'].includes(input.action) ? input.action : 'unknown',
  metadata: input.metadata || {},
  timestamp: new Date().toISOString()
};

return {
  json: {
    valid: true,
    data: sanitized,
    correlationId: $input.first().json.headers?.['x-correlation-id'] || Math.random().toString(36).substring(7)
  }
};

// Business logic: Create operation
const input = $input.first().json;
const correlationId = input.correlationId;
const data = input.data;

// Simulate service layer
const result = {
  id: Math.random().toString(36).substring(7),
  name: data.name,
  action: 'create',
  status: 'created',
  createdAt: new Date().toISOString(),
  correlationId: correlationId
};

// Return structured response
return {
  json: {
    success: true,
    operation: 'create',
    result: result,
    correlationId: correlationId
  }
};

// Business logic: Update operation
const input = $input.first().json;
const correlationId = input.correlationId;
const data = input.data;

// Simulate service layer
const result = {
  id: data.metadata?.id || 'unknown',
  name: data.name,
  action: 'update',
  status: 'updated',
  updatedAt: new Date().toISOString(),
  correlationId: correlationId
};

return {
  json: {
    success: true,
    operation: 'update',
    result: result,
    correlationId: correlationId
  }
};

// Business logic: Delete operation
const input = $input.first().json;
const correlationId = input.correlationId;
const data = input.data;

// Simulate service layer
const result = {
  id: data.metadata?.id || 'unknown',
  name: data.name,
  action: 'delete',
  status: 'deleted',
  deletedAt: new Date().toISOString(),
  correlationId: correlationId
};

return {
  json: {
    success: true,
    operation: 'delete',
    result: result,
    correlationId: correlationId
  }
};

// Business logic: Unknown action
const input = $input.first().json;

return {
  json: {
    success: false,
    operation: 'unknown',
    error: `Unknown action: ${input.data?.action}`,
    correlationId: input.correlationId,
    supportedActions: ['create', 'update', 'delete']
  }
};

// Logging layer
const result = $input.first().json;

// Structured logging
const logEntry = {
  timestamp: new Date().toISOString(),
  level: result.success ? 'info' : 'error',
  correlationId: result.correlationId,
  operation: result.operation,
  success: result.success,
  error: result.error || null
};

console.log('[LOG]', JSON.stringify(logEntry));

return { json: logEntry };
